def word_count(text: str) -> dict:
    if not text:
        return {}

    words = text.lower().split()
    word_counts = {}

    for word in words:
        word = ''.join(e for e in word if e.isalnum())
        if word not in word_counts:
            word_counts[word] = 0
        word_counts[word] += 1

    return word_counts
```
